      "description": "Бесплатные словесные и словарные игры для вашего класса — никаких учетных записей студентов, никакой рекламы, никаких загрузок. Внесите свои собственные списки слов, запустите целый класс многопользовательских на 5 языках.",
      "ogTitle": "Бесплатные словесные и словарные игры для класса",
      "ogDescription": "Никаких входов студентов, никакой рекламы — внесите свои собственные списки слов и запустите целый класс словесных игр на 5 языках."
