      "title": "Словарные дуэли — студент против студента словесные баталии",
      "description": "Вызовите одноклассников на словарные дуэли! Словесные баталии один-на-один в реальном времени которые тестируют правописание, словарный запас и быстрое мышление в образовательных условиях.",
      "ogTitle": "Словарные дуэли - LexiClash Education",
      "ogDescription": "Словесные баталии студент против студента один-на-один для практики словаря!"
