      "feature2Desc": "Одинаковый пазл для всех во всём мире каждый день. Отслеживай свою серию и поделись результатами эмодзи — как Wordle.",
      "feature3Title": "Режим приключений",
      "feature3Desc": "100 уровней в 10 тематических мирах. Спецплитки, битвы боссов, и пауэр-апы держат каждый раунд свежим.",
      "feature4Title": "5 языков",
      "feature4TitleShort": "Режим взрыва",
      "feature4Desc": "Играй на английском, иврите, шведском, японском или испанском. Переключайся в любое время и вызывай друзей на разные языки.",
      "modeTagMultiplayer": "2-20 игроков",
